{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Panel content."
    },
    {
      "name": "hasDivider",
      "type": "boolean",
      "description": "Line on the edge that faces the content: the inline end in the start slot, the inline start in the end slot. Without it and without padding, the panel and the content share one gap. The Layout's defaultHasDividers does not apply. Beside a ResizeHandle that draws its own line, leave it false.",
      "default": "false"
    },
    {
      "name": "padding",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Internal padding on every edge, using the spacing scale. Replaces the automatic inset and the gap shared with the content. 0 is full bleed."
    },
    {
      "name": "isScrollable",
      "type": "boolean",
      "description": "Enable scrollable overflow.",
      "default": "true"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label for the landmark element. While the region scrolls, it also names the scrolling region, which otherwise takes a translated \"Content\"."
    },
    {
      "name": "role",
      "type": "AriaRole",
      "description": "ARIA landmark role."
    },
    {
      "name": "width",
      "type": "number | string",
      "description": "Width of the panel. Numbers are treated as pixels, strings are used as-is. Ignored when resizable is provided; the hook controls width. Beside a ResizeHandle given a useResizable region's props, a panel at width={region.size} is inert while the region is collapsed, and focus inside it moves to the handle as it collapses."
    },
    {
      "name": "resizable",
      "type": "ResizableRegion | ResizableProps",
      "description": "The output of useResizable(), or its props. When provided, the hook drives the panel width and a ResizeHandle should be placed adjacent to the panel. Carries the region's axis ('horizontal' | 'vertical'), which must match the adjacent ResizeHandle's direction. With the hook's own value, the panel slides closed and open from the edge facing its ResizeHandle; a hand-built object does not slide. Either way, focus inside the panel moves to its ResizeHandle as it collapses, and the panel is inert while collapsed."
    },
    {
      "name": "ref",
      "type": "React.Ref<HTMLDivElement>",
      "description": "Ref forwarded to the panel element."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
